('490bcb60-6323-4660-ae99-756820aca3f8', '調布市総合体育館 室内プール', '東京都', '調布市', 'open', '東京都調布市深大寺北町2-1-65', 35.672825, 139.55014, 'https://www.city.chofu.lg.jp/040070/p026069.html', true, '', '9:00〜20:30', '第1・第3月曜日（祝日の場合は開館）、12月29日〜1月3日', '大人 1時間15分以内200円、2時間30分以内400円（超過1時間ごと160円）
子ども 70円／150円', true, false, null, null, null, null, true, '調布駅北口またはつつじヶ丘駅から京王バス「調布市総合体育館前」下車、徒歩約3分', '25m×6コース。小学生以上が利用可能。駐車場は第1（市内在住65歳以上・障害のある方専用）と第2（神代植物公園駐車場・有料）。', 'https://www.city.chofu.lg.jp/documents/2479/guidebook.pdf', '2026-10-21'),
('584d7f69-a8ab-4ae0-bba2-fe3db1fd05e8', '調和小学校屋内プール', '東京都', '調布市', 'open', '東京都調布市西つつじヶ丘4-22-6', 35.651386, 139.57373, 'https://www.city.chofu.lg.jp/040070/p026100.html', true, '', '9:00〜20:30（最終入場19:30）。学校授業での使用時は利用不可', '第2・第4月曜日（祝日の場合は翌日）、12月29日〜1月3日', '大人 1時間15分200円、2時間30分400円', true, false, true, null, null, null, false, '京王線つつじヶ丘駅または柴崎駅から徒歩約12分', '25m×5コース（可動床）、幼児用プール8m×3.5m。利用は調布市に在住・在学・在勤の方のみ。', 'https://www.city.chofu.lg.jp/040070/p026100.html', '2026-10-21'),
('c2d5b592-4066-4d45-9bc6-f79268a80719', '調布市市民プール', '東京都', '調布市', 'closed', '東京都調布市染地2-43-1', 35.640045, 139.547165, 'https://www.city.chofu.lg.jp/040070/p026313.html', false, '夏季のみ（閉鎖中）', '', '', '', true, true, true, null, null, null, null, '調布駅南口から多摩川住宅西行きバス「市民プール」下車。京王多摩川駅から東へ徒歩約15分', '閉鎖中。市は屋外プールとしての現状のままの改修・建替えは行わない方針を示している。営業時は50m×8コース、25m×6コース、変形プール、幼児用プール。', 'https://www.city.chofu.lg.jp/040070/p026313.html', '2026-10-21'),
('8ab71834-d608-419b-a111-e16c5d64b8f5', '京王アリーナTOKYO（武蔵野の森総合スポーツプラザ）プール', '東京都', '調布市', 'open', '東京都調布市西町290-11', 35.666344, 139.52269, 'https://keio-arena.tokyo/facility/pool.php', true, '', '', '', '個人利用 3時間まで500円（トレーニングルームと共通）', true, true, null, null, null, null, true, '京王線飛田給駅から徒歩', '東京都の施設。50m×20m・8コースを可動壁で25m×2面に分割可能。火〜土曜は25mコース、日・月曜は50mコース。3歳から利用可能（条件あり）。', 'https://keio-arena.tokyo/facility/pool.php', '2026-10-21'),
('388e2819-a141-447c-9fdd-c859c1c3cdb0', 'SUBARU総合スポーツセンター 屋内プール', '東京都', '三鷹市', 'open', '東京都三鷹市新川6-37-1', 35.681446, 139.561462, 'https://www.mitakagenki-plaza.jp/sports/index1023.html', true, '', '9:00〜22:00', '', '大人 市内在住 1時間200円・2時間400円、市外 1時間300円・2時間600円', null, null, null, null, null, null, true, '三鷹・吉祥寺・調布・武蔵境・仙川の各駅から京王バス等で「三鷹市役所前」または「三鷹農協前」下車、徒歩約5分', '三鷹市元気創造プラザ内。駐車場は三鷹市役所駐車場を利用（施設利用者は3時間まで無料）。調布市民は三鷹市民と同じ料金で利用可能（調布市の案内による）。', 'https://www.mitakagenki-plaza.jp/access.html', '2026-10-21'),
('ce7e32c6-bb95-42c1-8180-ffb10e3020f1', '両国屋内プール', '東京都', '墨田区', 'open', '東京都墨田区横網1-8-1', 35.698643, 139.796173, 'https://www.city.sumida.lg.jp/sisetu_info/sports/ryougoku/index.html', true, '', '9:00〜12:00、12:30〜15:30、16:00〜21:00（各枠の終了15分前まで遊泳可）', '毎週火曜日（祝日の場合は翌水曜日）、年末年始、点検・清掃日', '', true, false, null, null, null, null, null, '両国駅周辺', '25m×7コース、可動床で水深約0.5〜1.6m。日本水泳連盟公認。', 'https://information.konamisportsclub.jp/trust/ryogoku/', '2026-10-21'),
('bf48272c-bdd9-41d8-842c-8a0cc1a853c3', 'スイムスポーツセンター（竹の塚温水プール）', '東京都', '足立区', 'open', '東京都足立区西保木間4-10-1', 35.803596, 139.797333, 'https://www.city.adachi.tokyo.jp/sports/shisetsu/swim.html', true, '', '9:30〜20:30', '第3月曜日（祝日の場合は翌日）、12月29日〜1月3日', '16歳以上 1回550円、2歳〜中学生 100円', true, false, true, null, null, null, true, '北千住駅から都営バス北47「足立清掃工場前」、または西新井駅東口から東武バス竹13・竹14「足立清掃工場前」下車、徒歩約1分', '25m×9コース。駐車場は地下26台（30分100円、最大800円）。', 'https://www.city.adachi.tokyo.jp/sports/shisetsu/koen/034.html', '2026-10-21'),
('71c3c68f-2c2e-42fa-bbab-489686f65b6e', '町田市立室内プール', '東京都', '町田市', 'open', '東京都町田市図師町199-1', 35.586166, 139.412659, null, true, '', '9:00〜21:00', '第1・第3月曜日（祝日の場合は翌日）。7月21日〜8月31日は無休。年末年始', '大人 プールのみ460円', true, true, true, null, null, null, null, '', '50m公認プール、25mプール、幼児用プール。夏季のみおむつの取れていない子ども向けの水遊び場あり。', 'https://summer.walkerplus.com/odekake/detail/ar0313s12415/data.html', '2026-10-21'),
('adb7e6ee-07ee-4c20-88fa-ff361e2fe1e9', '引地台温水プール', '神奈川県', '大和市', 'open', '神奈川県大和市柳橋4-5000', 35.455681, 139.46106, null, true, '', '10:00〜20:00（7月20日〜8月31日は9:30〜20:00）', '月曜日（祝日の場合は翌日）。7月20日〜8月31日は営業。年末年始', '大人 4〜6月・9月 1回400円、7・8月 2時間400円、10〜3月 1回300円', true, null, true, null, true, true, true, '引地台公園内', '25mプールを囲む約120mの流水プール、ウォータースライダー（40m・80m）、ジャグジー、採暖室。', 'https://iko-yo.net/facilities/2827', '2026-10-21'),
('eaba8bb1-ba14-4bf7-8c2c-3883ef7e9895', '国分寺市民室内プール', '東京都', '国分寺市', 'temporarily_closed', '東京都国分寺市西恋ヶ窪3-32-6', 35.705685, 139.465408, 'https://www.city.kokubunji.tokyo.jp/shisetsu/sport/pool/1004201.html', true, '', '9:00〜22:30', '第1月曜日（祝日の場合は翌日）、年末年始', '大人 1時間200円、2時間400円', true, false, true, null, null, null, true, 'JR西国分寺駅または西武線恋ヶ窪駅から徒歩約10分', '2025年9月12日から天井の耐震性の問題で利用停止。改修工事は2026年10月〜2027年4月の予定で、再開時期は未定。25m×6コース、幼児用プール9m×4m。', 'https://www.city.kokubunji.tokyo.jp/kurashi/1011357/1011397/1009662.html', '2026-10-21'),
('eacb7e40-bba5-4b7f-9f50-5fecb95e990b', '池袋スポーツセンター', '東京都', '豊島区', 'temporarily_closed', '東京都豊島区上池袋2-5-1', 35.734627, 139.715485, 'https://www.city.toshima.lg.jp/501/bunka/sports/sports/003418/003496.html', true, '', '月〜土・祝 8:30〜22:00、日 8:30〜21:00', '第2月曜日、12月30日〜1月3日、6月・11月中旬の約5日間', '大人 2時間400円（超過1時間200円）', null, null, null, null, null, null, null, '', '健康プラザとしま11階の温水プール。改修工事のため2025年12月15日〜2027年3月12日（予定）休場。', 'https://www.city.toshima.lg.jp/501/sports/2511110936.html', '2026-10-21'),
('d31c4450-d6cc-4267-9502-82e720e158f7', 'サンアール朝日', '埼玉県', '川口市', 'open', '埼玉県川口市朝日4-21-33', 35.811607, 139.744064, 'https://www.city.kawaguchi.lg.jp/soshiki/01100/090/1/19775.html', true, '', '', '', '', false, false, null, null, null, null, true, '', '朝日環境センターの余熱利用施設（リサイクルプラザ5階）。20mプール（遊泳・歩行コース）と、水着で利用する健康浴場（気泡浴、屋上風呂、ミストサウナなど）。駐車場約100台（無料）。', 'https://www.city.kawaguchi.lg.jp/soshiki/04010/070/1/4452.html', '2026-10-21'),
('7c484e81-7300-46c6-8abb-9a6643b61a8b', '川口市西スポーツセンター', '埼玉県', '川口市', 'open', '埼玉県川口市川口6-9-29', 35.804897, 139.708786, 'https://www.city.kawaguchi.lg.jp/soshiki/04010/070/1/2/index.html', true, '', '', '', '', true, null, true, null, true, null, null, '', '温水プール。25mプール、流水プール、幼児プール、ウォータースライダー、マウンテンスライダー、採暖槽。', 'https://www.city.kawaguchi.lg.jp/soshiki/04010/070/1/4452.html', '2026-10-21'),
('8dc9951b-cb92-4499-9f61-145197602bcd', '稲毛海浜公園プール', '千葉県', '千葉市', 'open', '千葉県千葉市美浜区高浜7-1-1', 35.614758, 140.066299, 'https://sunsetbeachpark.jp/', false, '夏季のみ（2026年は7月11日〜9月23日、9月は土日祝のみ）', '10:00〜17:00（最終入場16:00）、8月は20:00まで', '', '', true, false, true, null, true, null, null, '', '波のプール、25mプール、流れるプール、キッズプール、フロートスライダー（身長120cm以上）など。悪天候時は休場。', 'https://summer.walkerplus.com/odekake/detail/ar0312s13785/data.html', '2026-10-21'),
('b4819211-b257-4e0f-b4f4-51437f70cc54', '白岡市B&G海洋センター（温水プール）', '埼玉県', '白岡市', 'open', '埼玉県白岡市千駄野432', 36.018742, 139.676514, 'https://www.city.shiraoka.lg.jp/kurashi_tetsuzuki/kokyoshisetsu/4/index.html', true, '', '', '', '', null, null, null, null, null, null, null, '', '', 'https://www.city.shiraoka.lg.jp/kurashi_tetsuzuki/kokyoshisetsu/4/index.html', '2026-10-21'),
('354746da-148f-40f8-868a-5d854d9e8b72', 'サンフロッグ春日井', '愛知県', '春日井市', 'open', '愛知県春日井市南下原町2-4-11', 35.270226, 136.974991, null, true, '', '平日13:00〜20:30、土日祝10:00〜20:30（夏休み期間は平日10:00〜、土日祝9:00〜）', '月曜日（祝日の場合は直後の平日）。夏休み期間は営業。12月29日〜1月3日', '大人 1回500円', null, null, true, null, true, null, true, '', '完全屋内温水プール。流水プール、大小2つのウォータースライダー、幼児用プール、競技用プール。駐車場770台（無料・総合体育館と共用）。', 'https://aichinow.pref.aichi.jp/spots/detail/1548/', '2026-10-21'),
('42e7b3c7-7acb-42eb-a972-ca448e8a09d9', '豊田地域文化広場 プール', '愛知県', '豊田市', 'open', '愛知県豊田市西田町けやき1', 35.026173, 137.12439, null, true, '', '', '月曜日（祝日は開館）、12月28日〜1月4日', '', true, null, null, null, null, null, true, '', '屋内温水プール。大人用・子ども用の25mプール（計7コース）。', 'https://report.iko-yo.net/articles/20376', '2026-10-21'),
('0a7694d3-c592-4ca9-bfe7-d550607765d9', '和布刈塩水プール', '福岡県', '北九州市', 'open', '福岡県北九州市門司区大字門司3491-1', 33.958336, 130.963684, 'https://www.city.kitakyushu.lg.jp/contents/924_01666.html', false, '夏季のみ（2026年は7月1日〜8月31日）', '9:30〜17:00', '', '大人（一般）1回2時間以内360円', true, true, true, null, null, null, true, '和布刈公園内', '関門海峡の海水を使う屋外プール。50m×9レーン、25m×7レーン、幼児用、遊戯用。駐車場90台。', 'https://www.city.kitakyushu.lg.jp/contents/924_01666.html', '2026-10-21')
on conflict (id) do nothing;

